const input = $input.first().json;
let response = input.text || input.content || input;

let result;
try {
  if (typeof response === 'object') {
    result = response;
  } else {
    const jsonMatch = response.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      result = JSON.parse(jsonMatch[0]);
    } else {
      result = { raw: response };
    }
  }
} catch (e) {
  result = { raw: response, error: e.message };
}

return [{
  json: {
    ...result,
    checked_at: new Date().toISOString()
  }
}];
